import { RspackConfigMutator, RspackConfigTransformer } from '@teambit/rspack.modules.rspack-config-mutator';
import type { Configuration as DevServerConfiguration } from '@rspack/dev-server';

export function createCacheControlTransformer(): RspackConfigTransformer {
  return (configMutator: RspackConfigMutator) => {
    const config = configMutator.raw;
    config.devtool = 'eval-cheap-module-source-map';

    if (!config.optimization) {
      config.optimization = {};
    }
    if (!config.devServer) {
      config.devServer = {};
    }
    config.optimization = {
      ...(config.optimization || {}),
      minimize: false,
      concatenateModules: true,
      moduleIds: 'named',
      runtimeChunk: 'single',
      splitChunks: {
        chunks: 'all',
        maxInitialRequests: 2,
        minSize: 2000000,
        maxSize: 5000000,
        cacheGroups: {
          vendors: {
            // keep stylesheets with their importing chunk: extracted css order
            // inside a shared vendors chunk is arbitrary across entries, which
            // breaks cascade order for css-modules that use :global or element
            // selectors ("Conflicting order" warnings, nondeterministic styling).
            test: (module: { resource?: string; type?: string }) =>
              !/\.(css|scss|sass|less)/.test(module.resource ?? '') &&
              !String(module.type ?? '').startsWith('css') &&
              /[\\/]node_modules[\\/]/.test(module.resource ?? ''),
            name: 'vendors',
            priority: 30,
            enforce: true,
            reuseExistingChunk: true,
          },
          main: {
            test: /\.(js|jsx|ts|tsx)$/,
            name: 'main',
            priority: 10,
            enforce: true,
            chunks: 'all',
          },
        },
      },
    };

    const originalSetupMiddlewares = config.devServer.setupMiddlewares;

    config.devServer.setupMiddlewares = (middlewares: any[], devServer: DevServerConfiguration) => {
      middlewares.unshift({
        name: 'performance-middleware',
        middleware: (req: any, res: any, next: any) => {
          const reqPath = req.path || req.url || '';
          if (reqPath.endsWith('.js')) {
            res.setHeader('Cache-Control', 'no-cache');
          }
          if (reqPath === '/' || reqPath.endsWith('.html')) {
            res.setHeader('Cache-Control', 'public, max-age=1');
          }
          next();
        },
      });

      return typeof originalSetupMiddlewares === 'function'
        ? originalSetupMiddlewares(middlewares, devServer)
        : middlewares;
    };

    return configMutator;
  };
}
